// Normalized lookup map to handle subtle spacing or naming discrepancies
const NORMALIZED_CDN_MAP = new Map<string, string>();

// Populate normalized map
for (const [key, id] of Object.entries(GOOGLE_DRIVE_IMAGE_CDN)) {
  const norm = key.toLowerCase().replace(/\.jpe?g$/i, '').replace(/[^a-z0-9]/g, '');
  if (!NORMALIZED_CDN_MAP.has(norm)) {
    NORMALIZED_CDN_MAP.set(norm, id);
  }
}

/**
 * Returns an optimized Google UserContent CDN URL for a given vehicle image filename.
 * Supports flexible dimensions, automatic WebP transcoding, and space/case normalization.
 */
export function getOptimizedDriveUrl(filename?: string, width: number = 720): string | null {
  if (!filename) return null;
  const clean = filename.trim().replace(/^public\//, "").replace(/^\//, "");
  
  // Clean valid positive width constraint with -rw for high performance WebP
  const targetWidth = Math.max(120, Math.min(2048, width || 720));

  // 1. Direct match
  if (GOOGLE_DRIVE_IMAGE_CDN[clean]) {
    return `https://lh3.googleusercontent.com/d/${GOOGLE_DRIVE_IMAGE_CDN[clean]}=w${targetWidth}-rw`;
  }

  // 2. Normalized match (handles spaces, mian vs main, 1 main vs main image, etc.)
  const norm = clean.toLowerCase().replace(/\.jpe?g$/i, "").replace(/[^a-z0-9]/g, "");
  if (NORMALIZED_CDN_MAP.has(norm)) {
    return `https://lh3.googleusercontent.com/d/${NORMALIZED_CDN_MAP.get(norm)}=w${targetWidth}-rw`;
  }

  // 3. Fallback for common synonyms like "1 main image" -> "main image"
  const altNorm = norm.replace(/1mainimage/, "mainimage").replace(/mainimg/, "mainimage");
  if (NORMALIZED_CDN_MAP.has(altNorm)) {
    return `https://lh3.googleusercontent.com/d/${NORMALIZED_CDN_MAP.get(altNorm)}=w${targetWidth}-rw`;
  }

  // 4. Strip emojis/special characters if any
  const asciiNorm = clean.replace(/[^a-zA-Z0-9._ -]/g, '').toLowerCase().replace(/\.jpe?g$/i, '').replace(/[^a-z0-9]/g, '');
  if (NORMALIZED_CDN_MAP.has(asciiNorm)) {
    return `https://lh3.googleusercontent.com/d/${NORMALIZED_CDN_MAP.get(asciiNorm)}=w${targetWidth}-rw`;
  }

  return null;
}

export const getDriveImageUrl = getOptimizedDriveUrl;
